// ---------------------------------------------------------------------------
// Knowledge API (unified — LangChain + Milvus Lite engine)
// ---------------------------------------------------------------------------

// Current agent context — set by the app when agent is selected
let _knowledgeAgentId = "default";
function setKnowledgeAgentId(agentId) {
  _knowledgeAgentId = agentId;
}

/**
 * Central knowledge API helper. Injects X-Agent-ID and optional X-Thread-ID
 * on every knowledge request. All knowledge calls MUST go through this helper.
 */
function knowledgeApiFetch(url, init, threadId) {
  const headers = {
    ...(init?.headers || {}),
    "X-Agent-ID": _knowledgeAgentId
  };
  if (threadId) {
    headers["X-Thread-ID"] = threadId;
  }
  return apiFetch(url, {
    ...init,
    headers
  });
}

// --- Health & Settings ---

function getKnowledgeHealth() {
  return knowledgeApiFetch("/api/knowledge/health");
}
function enableKnowledge() {
  return knowledgeApiFetch("/api/knowledge/enable", {
    method: "POST"
  });
}
function getKnowledgeSettings() {
  return knowledgeApiFetch("/api/knowledge/settings");
}
function updateKnowledgeSettings(settings) {
  return knowledgeApiFetch("/api/knowledge/settings", {
    method: "POST",
    headers: {
      "Content-Type": "application/json"
    },
    body: JSON.stringify(settings)
  });
}

// --- Documents (agent scope) ---

function uploadKnowledgeDocuments(files, replaceDuplicates = true) {
  const formData = new FormData();
  files.forEach(f => formData.append("files", f));
  formData.append("scope", "agent");
  formData.append("replace_duplicates", String(replaceDuplicates));
  return knowledgeApiFetch("/api/knowledge/documents", {
    method: "POST",
    body: formData
  });
}
function uploadKnowledgeDocument(file, replaceDuplicates = true) {
  const formData = new FormData();
  formData.append("files", file);
  formData.append("scope", "agent");
  formData.append("replace_duplicates", String(replaceDuplicates));
  return knowledgeApiFetch("/api/knowledge/documents", {
    method: "POST",
    body: formData
  });
}
function listKnowledgeDocuments() {
  return knowledgeApiFetch("/api/knowledge/documents?scope=agent");
}
function deleteKnowledgeDocument(filename) {
  return knowledgeApiFetch("/api/knowledge/documents", {
    method: "DELETE",
    headers: {
      "Content-Type": "application/json"
    },
    body: JSON.stringify({
      scope: "agent",
      filename
    })
  });
}
function getKnowledgeDocumentFile(scope, filename, threadId) {
  const params = new URLSearchParams({
    scope,
    filename
  });
  return knowledgeApiFetch(`/api/knowledge/documents/file?${params.toString()}`, undefined, threadId);
}

// --- Search ---

function searchKnowledge(query, limit = 10, scoreThreshold = 0) {
  return knowledgeApiFetch("/api/knowledge/search", {
    method: "POST",
    headers: {
      "Content-Type": "application/json"
    },
    body: JSON.stringify({
      scope: "agent",
      query,
      limit,
      score_threshold: scoreThreshold,
      include_scores: true
    })
  });
}

// --- Tasks ---

function getKnowledgeTasks() {
  return knowledgeApiFetch("/api/knowledge/tasks?scope=agent");
}
function getKnowledgeTaskStatus(taskId) {
  return knowledgeApiFetch(`/api/knowledge/tasks/${encodeURIComponent(taskId)}`);
}
function cancelKnowledgeTask(taskId) {
  return knowledgeApiFetch(`/api/knowledge/tasks/${encodeURIComponent(taskId)}/cancel`, {
    method: "POST"
  });
}

// ---------------------------------------------------------------------------
// Session-level knowledge (scope=session via unified API)
// ---------------------------------------------------------------------------

function uploadSessionKnowledgeDocuments(threadId, files, replaceDuplicates = true) {
  const formData = new FormData();
  files.forEach(f => formData.append("files", f));
  formData.append("scope", "session");
  formData.append("replace_duplicates", String(replaceDuplicates));
  return knowledgeApiFetch("/api/knowledge/documents", {
    method: "POST",
    body: formData
  }, threadId);
}
function listSessionKnowledgeDocuments(threadId) {
  return knowledgeApiFetch("/api/knowledge/documents?scope=session", undefined, threadId);
}
function deleteSessionKnowledgeDocument(threadId, filename) {
  return knowledgeApiFetch("/api/knowledge/documents", {
    method: "DELETE",
    headers: {
      "Content-Type": "application/json"
    },
    body: JSON.stringify({
      scope: "session",
      filename
    })
  }, threadId);
}
function deleteSessionKnowledgeCollection(threadId) {
  return knowledgeApiFetch("/api/knowledge/session", {
    method: "DELETE"
  }, threadId);
}

